CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT, guest BOOLEAN DEFAULT false, points INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS matches(id UUID PRIMARY KEY, winner TEXT, result JSONB, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS point_events(id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),amount INTEGER NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT now());